#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pwd.h>

#define SESSION_DIR "/var/run/sessions"
#define MAX_USERNAME 64
#define MAX_DATA 4096

static int validate_username(const char *username) {
    if (!username || strlen(username) == 0 || strlen(username) >= MAX_USERNAME)
        return -1;
    for (const char *p = username; *p; p++) {
        if (!((*p >= 'a' && *p <= 'z') || (*p >= '0' && *p <= '9') || *p == '_'))
            return -1;
    }
    return 0;
}

static int build_session_path(const char *username, char *path, size_t pathlen) {
    int ret = snprintf(path, pathlen, "%s/%s.session", SESSION_DIR, username);
    if (ret < 0 || (size_t)ret >= pathlen)
        return -1;
    return 0;
}

/* Write session data for the given user.
 * Security model: only the user themselves or root can write to their session file.
 * The file must be owned by the target user and be a regular file (no symlinks). */
int write_session(const char *username, const char *data, size_t data_len, uid_t caller_uid) {
    char path[256];
    struct stat st;
    int fd;
    struct passwd *pw;

    if (validate_username(username) != 0)
        return -1;
    if (!data || data_len == 0 || data_len > MAX_DATA)
        return -1;
    if (build_session_path(username, path, sizeof(path)) != 0)
        return -1;

    /* Look up the target user's UID */
    pw = getpwnam(username);
    if (!pw)
        return -1;

    /* Authorization check: caller must be root or the target user */
    if (caller_uid != 0 && caller_uid != pw->pw_uid)
        return -1;

    /* Security check: verify the file exists, is a regular file, and is owned by target user */
    if (lstat(path, &st) != 0)
        return -1;
    if (!S_ISREG(st.st_mode))
        return -1;
    if (st.st_uid != pw->pw_uid)
        return -1;
    /* Ensure no world-writable permissions */
    if (st.st_mode & S_IWOTH)
        return -1;

    /* Open the verified file and write session data */
    fd = open(path, O_WRONLY | O_TRUNC);
    if (fd < 0)
        return -1;

    ssize_t written = write(fd, data, data_len);
    close(fd);

    if (written < 0 || (size_t)written != data_len)
        return -1;

    return 0;
}

/* Read session data for the given user */
int read_session(const char *username, char *buf, size_t buflen, size_t *out_len, uid_t caller_uid) {
    char path[256];
    struct stat st;
    int fd;
    struct passwd *pw;

    if (validate_username(username) != 0)
        return -1;
    if (!buf || buflen == 0)
        return -1;
    if (build_session_path(username, path, sizeof(path)) != 0)
        return -1;

    pw = getpwnam(username);
    if (!pw)
        return -1;

    if (caller_uid != 0 && caller_uid != pw->pw_uid)
        return -1;

    /* Security check: verify file properties before reading */
    if (lstat(path, &st) != 0)
        return -1;
    if (!S_ISREG(st.st_mode))
        return -1;
    if (st.st_uid != pw->pw_uid)
        return -1;
    if ((size_t)st.st_size > buflen)
        return -1;

    fd = open(path, O_RDONLY);
    if (fd < 0)
        return -1;

    ssize_t nread = read(fd, buf, buflen);
    close(fd);

    if (nread < 0)
        return -1;
    if (out_len)
        *out_len = (size_t)nread;
    return 0;
}

/* Delete a session file */
int delete_session(const char *username, uid_t caller_uid) {
    char path[256];
    struct stat st;
    struct passwd *pw;

    if (validate_username(username) != 0)
        return -1;
    if (build_session_path(username, path, sizeof(path)) != 0)
        return -1;

    pw = getpwnam(username);
    if (!pw)
        return -1;

    if (caller_uid != 0 && caller_uid != pw->pw_uid)
        return -1;

    if (lstat(path, &st) != 0)
        return -1;
    if (!S_ISREG(st.st_mode))
        return -1;
    if (st.st_uid != pw->pw_uid)
        return -1;

    if (unlink(path) != 0)
        return -1;
    return 0;
}
